insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-136","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Ammonia’s gram-molecular mass, with N = 14 and H = 1, is","options":["15 g","16 g","17 g","18 g"],"answer_index":2,"explanation":"$14 + 3(1) = 17$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-137","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen’s share of the mass of water, expressed as a percentage, is","options":["5.6%","11.1%","16.0%","18.0%"],"answer_index":1,"explanation":"Two grams of H in 18 g of water give $2/18 \\times 100 = 11.1\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-138","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Solid sodium hydroxide (Na = 23, O = 16, H = 1) has a molar mass of","options":["23 g mol$^{-1}$","39 g mol$^{-1}$","40 g mol$^{-1}$","58 g mol$^{-1}$"],"answer_index":2,"explanation":"$23 + 16 + 1 = 40$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-139","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The calcium content of pure $\\mathrm{CaCO_3}$ (M = 100 g mol$^{-1}$) by mass percent is","options":["12%","40%","48%","60%"],"answer_index":1,"explanation":"40 g of Ca in 100 g of carbonate is a 40% calcium assay.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-140","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Urea, $\\mathrm{NH_2CONH_2}$ (M = 60 g mol$^{-1}$), is valued as a fertiliser for nitrogen. The nitrogen mass percent in urea is","options":["23.3%","46.7%","53.3%","60.0%"],"answer_index":1,"explanation":"Two N atoms contribute 28 g in 60 g, so $28/60 \\times 100 = 46.7\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-141","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Potassium chlorate $\\mathrm{KClO_3}$ (M = 122.5 g mol$^{-1}$) releases oxygen on heating. Oxygen’s mass percent in $\\mathrm{KClO_3}$ is nearest to","options":["13.1%","26.1%","39.2%","52.2%"],"answer_index":2,"explanation":"Three oxygen atoms weigh 48 g in 122.5 g, giving $48/122.5 \\times 100 \\approx 39.2\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-142","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"From a 50 g laboratory sample of pure $\\mathrm{CaCO_3}$, the mass of oxygen that can be accounted for in the formula is","options":["16 g","24 g","32 g","48 g"],"answer_index":1,"explanation":"Oxygen is 48% of $\\mathrm{CaCO_3}$, so $0.48 \\times 50 = 24$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-143","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Blue vitriol $\\mathrm{CuSO_4 \\cdot 5H_2O}$ (M = 249.5 g mol$^{-1}$) loses its water of crystallisation on strong heating. The mass percent of water in the pentahydrate is nearest to","options":["18.0%","25.0%","36.1%","45.2%"],"answer_index":2,"explanation":"Five water molecules weigh 90 g in 249.5 g, so $90/249.5 \\times 100 \\approx 36.1\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-144","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Haematite $\\mathrm{Fe_2O_3}$ (M = 160 g mol$^{-1}$) is 70% iron by mass. An 80 g ore sample that is 80% pure $\\mathrm{Fe_2O_3}$ (rest gangue) contains iron weighing","options":["44.8 g","56.0 g","64.0 g","70.0 g"],"answer_index":0,"explanation":"Pure oxide in the ore is $0.80 \\times 80 = 64$ g; iron in that oxide is $0.70 \\times 64 = 44.8$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-145","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The empirical formula of a compound is the formula that shows","options":["the actual number of atoms in one molecule","the simplest whole-number ratio of the atoms present","only the metals in the compound","the percentage by mass of each element"],"answer_index":1,"explanation":"Empirical formulae give the smallest integer atom ratio, not necessarily the molecular formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
